SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, CASE WHEN amount >= 1470 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, SIZE(COLLECT_SET(status)) AS num_status, STDDEV_SAMP(amount) AS amount_stddev, SIZE(COLLECT_SET(method)) AS num_methods, GROUPING(DATE_TRUNC('QUARTER', paid_at)) AS grouping_id FROM payments GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', paid_at), CASE WHEN amount >= 1470 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('QUARTER', paid_at)))
